        Item { name: "pad", unit_price: 9, quantity: 2 },
        Item { name: "ink", unit_price: 5, quantity: 3 },
    )
    let mut total_cost = 0
    for item in items {
        let cost = item.unit_price * item.quantity
        total_cost += cost
        print_str(item.name)
        print_int(cost)
    }
    print_int(total_cost)
    let max_item = match items {
        vec() => None,
        vec(x, xs) => Some(x),
    }
    for item in items {
        if Some(item) == max_item {
            print_str(item.name)
        }
    }
}

